"""The app icon, from bonsai/resources (generated by packaging/make_icons.py)."""

from __future__ import annotations

import sys
from pathlib import Path

from PySide6.QtGui import QIcon, QPixmap

RESOURCES = Path(__file__).resolve().parent.parent / "resources"
SIZES = (16, 24, 32, 48, 64, 128, 256, 512)
APP_ID = "hiraethclub.Bonsai"


def app_icon() -> QIcon:
    """All sizes in one QIcon; Qt picks the small drawing at 16-32 px and the artwork above."""
    icon = QIcon()
    for size in SIZES:
        path = RESOURCES / f"icon-{size}.png"
        if path.exists():
            icon.addFile(str(path))
    return icon


def icon_pixmap(size: int) -> QPixmap:
    return app_icon().pixmap(size, size)


def set_windows_app_id() -> None:
    """Give Bonsai its own taskbar entry and icon on Windows (not Python's) when run from source."""
    if sys.platform != "win32":
        return
    try:
        import ctypes

        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(APP_ID)
    except (AttributeError, OSError):
        pass
